from decimal import Decimal
from ledgerly.adjustments import refund_shipping
from ledgerly.errors import BillingError
from ledgerly.models import Payment
from ledgerly import audit

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def mk(status="captured", amount="100.00", refunded="0.00"):
    return Payment("p","i",Decimal(amount),status=status,created_at=T0,captured_at=T0,refunded_amount=Decimal(refunded))

# zero
try: refund_shipping(mk(), Decimal("0"), T0); print("FAIL zero")
except BillingError as e: print("zero ok", e.code)
# negative
try: refund_shipping(mk(), Decimal("-1"), T0); print("FAIL neg")
except BillingError as e: print("neg ok", e.code)
# over
try: refund_shipping(mk(), Decimal("100.01"), T0); print("FAIL over")
except BillingError as e: print("over ok", e.code)
# non-captured
for st in ("authorized","voided","refunded"):
    try: refund_shipping(mk(status=st), Decimal("1"), T0); print("FAIL", st)
    except BillingError as e: print(st, "ok", e.code)
# full refund sets status
p = mk(); refund_shipping(p, Decimal("100.00"), T0); print("full", p.refunded_amount, p.status)
# partial then full
p = mk(); refund_shipping(p, Decimal("40"), T0); print("partial", p.refunded_amount, p.status)
refund_shipping(p, Decimal("60"), T0); print("then full", p.refunded_amount, p.status)
# approval
try: refund_shipping(mk(amount="1000.00"), Decimal("600"), T0); print("FAIL approval")
except BillingError as e: print("approval ok", e.code)
# idempotency
